let menu=[],cart=[],selectedOrderType='',currentCategory='',currentModalItem=null,deliveryCharge=DEFAULT_DELIVERY_CHARGE,grillSurcharge=DEFAULT_GRILL_SURCHARGE,frySurcharge=DEFAULT_FRY_SURCHARGE;
