const normalizePhone=p=>{let s=String(p||'').replace(/\D/g,'');if(!s)return '';if(s.startsWith('00961'))s=s.slice(5);else if(s.startsWith('961'))s=s.slice(3);if(s.startsWith('0'))s=s.slice(1);return s?'961'+s:''};

