async function api(path,opt={}){const headers=Object.assign({apikey:SUPABASE_KEY,Authorization:'Bearer '+SUPABASE_KEY,'Content-Type':'application/json'},opt.headers||{});return fetch(SUPABASE_URL+path,{...opt,headers})}
