function displayPrice(i){if(i.type==='weight')return `من $${money(i.pricing?.base)} / كغ`;if(i.type==='sizes')return `من $${money(Math.min(...Object.values(i.sizes||{0:0}).map(Number)))}`;if(i.type==='meal'){const price=currentCategory===SANDWICHES_CATEGORY?i.prices?.ساندويش:i.prices?.وجبة;return `$${money(price)}`}if(i.type==='offer')return `$${money(i.price)}`;return `$${money(i.price)}`}
function renderItems(){const box=document.getElementById('items');if(!box)return;if(!selectedOrderType){box.innerHTML='<div class="order-start-message">👆 اختار أولاً <b>دليفري</b> أو <b>استلام من المحل</b> حتى تبدأ بإضافة الطلب.</div>';return}const arr=menu.filter(i=>(currentCategory===MEALS_CATEGORY||currentCategory===SANDWICHES_CATEGORY)?i.type==='meal':i.category===currentCategory);box.innerHTML=arr.map(i=>{const sold=i.available===false;return `<div class="menu-item ${sold?'disabled':''}" onclick="openItem('${esc(i.id).replace(/'/g,"\\'")}')"><div class="menu-item-name">${esc(i.name)}</div><div class="menu-item-price">${sold?'❌ منتهي':displayPrice(i)}</div>${sold?'<span class="badge">منتهي</span>':''}</div>`}).join('')}
let modalPrep='raw',modalSize='',modalMeal='وجبة';
function qtyPad(inputId,decimals=false){return `<div class="qty-pad-wrap"><input id="${inputId}" class="modal-input qty-display" type="text" inputmode="decimal" value="${decimals?'1.0':'1'}" readonly><div class="qty-pad">${['7','8','9','4','5','6','1','2','3',decimals?'.':'0','0','⌫'].map(k=>`<button type="button" onclick="qtyPadPress('${inputId}','${k}')">${k}</button>`).join('')}<button type="button" class="qty-pad-clear" onclick="qtyPadClear('${inputId}')">C</button></div></div>`}
function qtyPadPress(id,key){const e=document.getElementById(id);if(!e)return;let v=e.value||'';if(key==='⌫'){e.value=v.slice(0,-1)||'0';return}if(key==='.') {if(!v.includes('.'))e.value=v+'.';return}if(v==='0')v='';e.value=v+key}
function qtyPadClear(id){const e=document.getElementById(id);if(e)e.value='0'}
function openItem(id){if(!selectedOrderType){alert('⚠️ أولاً اختار نوع الطلب: دليفري أو استلام من المحل.');return}const i=menu.find(x=>x.id===id);if(!i||i.available===false||!stockAvailable(i))return alert('هذا الصنف منتهي حالياً.');currentModalItem=i;modalPrep='raw';modalSize=Object.keys(i.sizes||{})[0]||'';modalMeal=currentCategory===SANDWICHES_CATEGORY?'ساندويش':'وجبة';let body='';
if(i.type==='offer')body=`<div class="offer-details"><h4>🎁 تفاصيل العرض</h4><p>${esc(i.details||'لا توجد تفاصيل إضافية.')}</p>${(i.items||[]).length?`<ul>${i.items.map(x=>`<li>${esc(x.name)}${x.quantity&&Number(x.quantity)>1?' × '+x.quantity:''}</li>`).join('')}</ul>`:''}</div><div class="option-group"><label>الكمية</label>${qtyPad("itemQty",false)}</div><div class="total">السعر: $${money(i.price)}</div>`;
else if(i.type==='weight')body=`<div class="option-group"><label>طريقة التحضير</label><div class="option-buttons"><button id="prep-raw" class="option-btn active" onclick="choosePrep('raw')">ني</button><button id="prep-fry" class="option-btn" onclick="choosePrep('fry')">قلي +$${money(frySurcharge)}</button><button id="prep-grill" class="option-btn" onclick="choosePrep('grill')">شوي +$${money(grillSurcharge)}</button></div></div><div class="option-group"><label>الكمية بالكيلو</label>${qtyPad("weightQty",true)}</div><div id="modalPrice" class="total">السعر: $${money(effectivePrice(i,'raw'))} / كغ</div>`;
else if(i.type==='sizes')body=`<div class="option-group"><label>الحجم</label><div class="size-options">${Object.entries(i.sizes||{}).map(([s,p],n)=>`<button class="size-option ${n===0?'active':''}" data-size="${esc(s)}" onclick="chooseSize(this)">${esc(s)}<br>$${money(p)}</button>`).join('')}</div></div><div class="option-group"><label>الكمية</label>${qtyPad("itemQty",false)}</div>`;
else if(i.type==='meal'){modalMeal=currentCategory===SANDWICHES_CATEGORY?'ساندويش':'وجبة';const shownPrice=modalMeal==='ساندويش'?i.prices?.ساندويش:i.prices?.وجبة;body=`<div class="option-group"><label>${modalMeal}</label><div class="selected-meal-price">$${money(shownPrice)}</div></div><div class="option-group"><label>الكمية</label>${qtyPad("itemQty",false)}</div>`;}
else body=`<div class="option-group"><label>الكمية</label>${qtyPad("itemQty",false)}</div>`;
document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal-box"><div class="modal-header"><h3>${i.type==='offer'?'🎁':'🐟'} ${esc(i.name)}</h3><button type="button" onclick="closeModal()">✕</button></div><div class="modal-body">${body}<button class="modal-confirm-btn" onclick="addModalItem()">➕ إضافة إلى الطلب</button></div></div></div>`}
function choosePrep(p){modalPrep=p;document.querySelectorAll('.option-btn').forEach(b=>b.classList.remove('active'));const b=document.getElementById('prep-'+p);if(b)b.classList.add('active');const el=document.getElementById('modalPrice');if(el&&currentModalItem)el.textContent=`السعر: $${money(effectivePrice(currentModalItem,p))} / كغ`}
function chooseSize(btn){modalSize=btn.dataset.size;document.querySelectorAll('.size-option').forEach(b=>b.classList.remove('active'));btn.classList.add('active')}
function chooseMeal(btn){modalMeal=btn.dataset.meal;document.querySelectorAll('[data-meal]').forEach(b=>b.classList.remove('active'));btn.classList.add('active')}
function addModalItem(){const i=currentModalItem;if(!i)return;let qty,unitPrice,label,weight=0;if(i.type==='offer'){qty=Number(document.getElementById('itemQty').value);unitPrice=Number(i.price||0);label=i.name}else if(i.type==='weight'){qty=Number(document.getElementById('weightQty').value);if(!Number.isFinite(qty)||qty<=0)return alert('أدخل كمية صحيحة بالكيلو.');unitPrice=effectivePrice(i,modalPrep);weight=qty;label=`${i.name} - ${modalPrep==='fry'?'قلي':modalPrep==='grill'?'شوي':'ني'}`}else if(i.type==='sizes'){qty=Number(document.getElementById('itemQty').value);unitPrice=Number(i.sizes?.[modalSize]||0);label=`${i.name} - ${modalSize}`}else if(i.type==='meal'){qty=Number(document.getElementById('itemQty').value);unitPrice=Number(i.prices?.[modalMeal]||0);label=`${i.name} - ${modalMeal}`}else{qty=Number(document.getElementById('itemQty').value);unitPrice=Number(i.price||0);label=i.name}if(!Number.isFinite(qty)||qty<=0)return alert('الكمية غير صحيحة.');cart.push({id:i.id,name:i.name,label,type:i.type,offerItems:i.type==='offer'?(i.items||[]):[],quantity:qty,weight,unitPrice,total:qty*unitPrice,preparation:i.type==='weight'?modalPrep:'',category:i.category});closeModal();renderCart()}
function renderCart(){const box=document.getElementById('cartItems');if(!box)return;let total=cart.reduce((s,x)=>s+Number(x.total),0);if(selectedOrderType==='Delivery'&&cart.length)total+=deliveryCharge;if(!cart.length)box.innerHTML='<p>لا يوجد أصناف</p>';else box.innerHTML=cart.map((x,n)=>`<div class="cart-item"><div><strong>${esc(x.label)}</strong><br><small>${x.weight?money(x.weight)+' كغ × ':x.quantity+' × '}$${money(x.unitPrice)}</small></div><div class="quantity"><button type="button" onclick="removeCartItem(${n})">−</button><b>${x.weight?money(x.weight)+' كغ':x.quantity}</b><button type="button" onclick="increaseCartItem(${n})">+</button></div></div>`).join('');document.getElementById('total').textContent=money(total)}
function removeCartItem(n){cart.splice(n,1);renderCart()}
function increaseCartItem(n){const x=cart[n];if(!x)return;if(x.weight)x.weight=Number(x.weight)+0.1;else x.quantity=Number(x.quantity)+1;x.total=Number(x.weight||x.quantity)*Number(x.unitPrice);renderCart()}
function clearOrder(){cart=[];selectedOrderType='';document.getElementById('orderType').textContent='لم يتم الاختيار';document.getElementById('deliveryBtn').classList.remove('active');document.getElementById('pickupBtn').classList.remove('active');['name','phone','address','deliveryTime','notes'].forEach(id=>{const e=document.getElementById(id);if(e)e.value=''});const dt=document.getElementById('deliveryTime');if(dt)dt.disabled=true;document.getElementById('customerMessage').textContent='';renderCategories();renderItems();renderCart()}
let customerLookupTimer=null,customerLookupToken=0;
function fillCustomer(c){document.getElementById('name').value=c.name||'';document.getElementById('address').value=c.address||'';document.getElementById('notes').value=c.notes||'';document.getElementById('customerMessage').textContent='✅ زبون موجود — تم تعبئة الاسم والعنوان تلقائياً'}
async function findCustomer(){const raw=String(document.getElementById('phone')?.value||'');const phone=normalizePhone(raw);const token=++customerLookupToken;if(phone.length<8)return;const setMessage=t=>{if(token===customerLookupToken){const e=document.getElementById('customerMessage');if(e)e.textContent=t}};try{const cached=JSON.parse(localStorage.getItem(CUSTOMER_STORAGE_KEY)||'[]');const variants=[phone,phone.replace(/^961/,'0'),'0'+phone.replace(/^961/,'')].filter((v,i,a)=>v&&a.indexOf(v)===i);let found=null;for(const v of variants){const r=await api(`/rest/v1/customers?phone=eq.${encodeURIComponent(v)}&select=*&limit=1`);if(token!==customerLookupToken)return;if(r.ok){const a=await r.json();if(a[0]){found=a[0];break}}}if(found){fillCustomer(found);const cache=Array.isArray(cached)?cached:[];const idx=cache.findIndex(c=>normalizePhone(c.phone)===phone);if(idx>=0)cache[idx]=found;else cache.unshift(found);localStorage.setItem(CUSTOMER_STORAGE_KEY,JSON.stringify(cache.slice(0,500)));return}const local=Array.isArray(cached)?cached.find(c=>normalizePhone(c.phone)===phone):null;if(local&&((local.name||'').trim()||(local.address||'').trim())){fillCustomer(local);return}setMessage('⚪ زبون جديد — أدخل الاسم والعنوان')}catch(e){console.warn('findCustomer',e);const cached=JSON.parse(localStorage.getItem(CUSTOMER_STORAGE_KEY)||'[]');const local=Array.isArray(cached)?cached.find(c=>normalizePhone(c.phone)===phone):null;if(local&&((local.name||'').trim()||(local.address||'').trim()))fillCustomer(local);else setMessage('⚪ تعذّر البحث — تأكد من الاتصال') }}
function queueCustomerLookup(){clearTimeout(customerLookupTimer);customerLookupTimer=setTimeout(findCustomer,300)}
async function saveCustomer(){const phone=normalizePhone(document.getElementById('phone').value),name=document.getElementById('name').value.trim(),address=document.getElementById('address').value.trim(),notes=document.getElementById('notes').value.trim();if(!phone||!navigator.onLine)return;try{const r=await api('/rest/v1/customers?on_conflict=phone',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({phone,name,address,notes,updated_at:new Date().toISOString()})});if(!r.ok)console.warn('customer save',r.status,await r.text())}catch(e){console.warn(e)}}
function paymentMeta(){const p=document.getElementById('paymentMethod').value;return p==='cash'?'كاش':p==='card'?'بطاقة':'تحويل'}
function orderPayload(){const baseTotal=cart.reduce((s,x)=>s+Number(x.total),0),delivery=selectedOrderType==='Delivery'?deliveryCharge:0,deliveryTime=document.getElementById('deliveryTime')?.value||'';const meta={__meta:true,payment_method:document.getElementById('paymentMethod').value,payment_label:paymentMeta(),delivery_charge:delivery,delivery_time:deliveryTime};return{order_type:selectedOrderType,customer_name:document.getElementById('name').value.trim(),customer_phone:normalizePhone(document.getElementById('phone').value),customer_address:document.getElementById('address').value.trim(),notes:document.getElementById('notes').value.trim(),items:[...cart,meta],total:baseTotal+delivery,device_id:deviceId,sync_status:navigator.onLine?'synced':'pending',created_at:new Date().toISOString(),delivery_charge:delivery}}
async function confirmOrder(){if(!selectedOrderType)return alert('اختار نوع الطلب أولاً.');if(!cart.length)return alert('أضف صنفاً واحداً على الأقل.');const payload=orderPayload();const finish=()=>{printOrder(payload);clearOrder()};try{const r=await api('/rest/v1/orders',{method:'POST',body:JSON.stringify(payload)});if(!r.ok)throw new Error(await r.text());saveCustomer().catch(()=>{});alert('✅ تم حفظ الطلب بنجاح');finish()}catch(e){const q=JSON.parse(localStorage.getItem(PENDING_ORDERS_KEY)||'[]');q.push(payload);localStorage.setItem(PENDING_ORDERS_KEY,JSON.stringify(q));alert('📴 تم حفظ الطلب على الجهاز وسيتم مزامنته عند عودة الإنترنت.');finish()}}
async function syncPendingOrders(){if(!navigator.onLine)return;const q=JSON.parse(localStorage.getItem(PENDING_ORDERS_KEY)||'[]');if(!q.length)return;const left=[];for(const o of q){try{const r=await api('/rest/v1/orders',{method:'POST',body:JSON.stringify(o)});if(!r.ok)throw 0}catch{left.push(o)}}localStorage.setItem(PENDING_ORDERS_KEY,JSON.stringify(left))}
