function showWhatsAppNotice(o){
  let n=document.getElementById('whatsappOrderNotice');
  if(!n){n=document.createElement('div');n.id='whatsappOrderNotice';n.style.cssText='position:fixed;top:16px;left:16px;right:16px;z-index:99999;background:#fff;border:2px solid #111;border-radius:14px;padding:14px;box-shadow:0 8px 30px rgba(0,0,0,.25);direction:rtl;text-align:right;font-family:Arial';document.body.appendChild(n)}
  const items=(Array.isArray(o.items)?o.items:[]).filter(x=>!x.__meta);
  n.innerHTML=`<div style="font-size:18px;font-weight:800">🔔 طلب WhatsApp جديد</div><div style="margin-top:6px"><b>${esc(o.customer_name||'زبون')}</b> — ${esc(o.customer_phone||'')}</div><div style="margin-top:4px">📦 ${esc(o.order_type||'')} — 💰 $${money(o.total)}</div><div style="margin-top:6px;font-size:12px">${items.map(x=>esc(x.label||x.name||'')).join('، ')}</div>`;
  n.style.display='block';
}
function hideWhatsAppNotice(){const n=document.getElementById('whatsappOrderNotice');if(n)n.style.display='none'}
async function markWhatsAppOrderProcessed(id){
  const r=await api(`/rest/v1/orders?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({sync_status:'synced'})});
  if(!r.ok)throw new Error(await r.text());
}
async function checkWhatsAppOrders(){
  if(!navigator.onLine||whatsappPollBusy)return;
  whatsappPollBusy=true;
  try{
    const r=await api('/rest/v1/orders?device_id=eq.whatsapp&sync_status=eq.pending&select=*&order=created_at.asc&limit=20');
    if(!r.ok)throw new Error(await r.text());
    const rows=await r.json();
    const seen=getWhatsAppSeen();
    for(const o of rows){
      const id=String(o.id||'');
      if(!id||seen.includes(id))continue;
      showWhatsAppNotice(o);
      try{
        await new Promise(resolve=>setTimeout(resolve,250));
        printOrder(o);
        await markWhatsAppOrderProcessed(id);
        rememberWhatsAppOrder(id);
      }catch(e){
        console.warn('WhatsApp order processing',e);
        // Keep the order pending so it can be retried after the problem is fixed.
      }
      setTimeout(hideWhatsAppNotice,2500);
    }
  }catch(e){console.warn('WhatsApp orders check',e)}finally{whatsappPollBusy=false}
}

function printOrder(o){
  const rawItems=Array.isArray(o.items)?o.items:[];
  const items=rawItems.filter(x=>!x.__meta);
  const meta=rawItems.find(x=>x.__meta)||{};
  const isDelivery=String(o.order_type||'').toLowerCase()==='delivery';
  const delivery=Number(o.delivery_charge||0);

  const itemTotal=items.reduce((sum,x)=>{
    const qty=Number(x.weight ?? x.quantity ?? 1);
    const unit=Number(x.unitPrice ?? x.price ?? x.unit_price ?? 0);
    const line=Number(x.total ?? x.line_total);
    return sum + (Number.isFinite(line) ? line : qty * unit);
  },0);

  const subtotal=Number.isFinite(Number(o.total)) ? Number(o.total)-delivery : itemTotal;
  const displayOrderType=isDelivery?'توصيل':'استلام من المحل';
  const cleanNotes=String(o.notes||'')
    .replace(/رقم\s*WhatsApp\s*:?[^.،\n]+[.،]?/gi,'')
    .replace(/كلفة\s*التوصيل[^.،\n]*[.،]?/gi,'')
    .replace(/السعر\s*يشمل[^.،\n]*[.،]?/gi,'')
    .replace(/^[.،\s]+|[.،\s]+$/g,'').trim();

  const orderShort=String(o.id||'').replace(/-/g,'').slice(-6).toUpperCase();
  const created=o.created_at?new Date(o.created_at):new Date();
  const date=created.toLocaleDateString('ar-LB');
  const time=created.toLocaleTimeString('ar-LB',{hour:'2-digit',minute:'2-digit'});
  const moneyHtml=v=>'<span dir="ltr" style="direction:ltr;unicode-bidi:isolate;white-space:nowrap">$'+money(v)+'</span>';

  const rows=items.map(x=>{
    const qty=Number(x.weight ?? x.quantity ?? 1);
    const unit=Number(x.unitPrice ?? x.price ?? x.unit_price ?? 0);
    const line=Number.isFinite(Number(x.total)) ? Number(x.total) : qty*unit;
    const preparation=x.preparation||'';
    const baseName=x.name||x.label||'صنف';
    const label=x.type==='weight' && preparation
      ? baseName+' - '+(preparation==='grill'?'مشوي':preparation==='fry'?'مقلي':preparation)
      : (x.label||baseName);
    const qtyText=x.weight!=null ? money(qty)+' كغ' : String(Number(x.quantity??1));
    const offerDetails=x.type==='offer'&&Array.isArray(x.offerItems)&&x.offerItems.length
      ? '<div style="font-size:8px;margin-top:1px;line-height:1.15">'+x.offerItems.map(ci=>'• '+esc(ci.name)+(Number(ci.quantity)>1?' × '+Number(ci.quantity):'')).join('<br>')+'</div>' : '';
    return '<div class="receipt-item-row">'+
      '<div class="receipt-total">'+moneyHtml(line)+'</div>'+
      '<div class="receipt-price">'+moneyHtml(unit)+'</div>'+
      '<div class="receipt-qty">'+esc(qtyText)+'</div>'+
      '<div class="receipt-name">'+esc(label)+offerDetails+'</div>'+
    '</div>';
  }).join('');

  const deliveryHtml=isDelivery?(delivery>0?moneyHtml(delivery):'يحدد حسب المنطقة'):moneyHtml(0);
  const finalLabel=isDelivery&&delivery<=0?'المجموع قبل التوصيل':'المجموع النهائي';
  const finalValue=isDelivery&&delivery<=0?subtotal:Number(o.total||0);

  // Embed the logo directly in the receipt. This avoids image-loading problems in browser/PrintNode printing.
  const logoSrc='data:image/png;base64,';

  const html=`<div style="width:72mm;max-width:72mm;margin:0 auto;font-family:Arial,sans-serif;direction:rtl;text-align:right;padding:1.5mm 0.5mm;box-sizing:border-box;color:#000;font-size:11px;line-height:1.22;overflow:hidden">
    <style>
      .receipt-items{width:100%;margin-top:2mm;font-size:9px;direction:ltr;box-sizing:border-box}
      .receipt-item-head,.receipt-item-row{display:grid;grid-template-columns:18mm 15mm 12mm 1fr;column-gap:0;align-items:center;box-sizing:border-box}
      .receipt-item-head{font-weight:900;border-top:1px solid #000;border-bottom:1px solid #000;padding:2.5px 0;direction:ltr}
      .receipt-item-head>div{text-align:center;white-space:nowrap}
      .receipt-item-head>div:last-child{text-align:right}
      .receipt-item-row{border-bottom:1px dotted #888;min-height:8mm;padding:3px 0;direction:ltr}
      .receipt-item-row>div{min-width:0;box-sizing:border-box}
      .receipt-total,.receipt-price{direction:ltr;text-align:center;white-space:nowrap;font-weight:700}
      .receipt-qty{text-align:center;white-space:nowrap;direction:ltr}
      .receipt-name{direction:rtl;text-align:right;font-weight:700;white-space:normal;overflow-wrap:anywhere;padding-right:1mm}
      .receipt-name div{font-weight:400}
    </style>
    <div style="text-align:center;direction:ltr">
      <img src="${logoSrc}" alt="Tabbara Fish" style="display:block;width:55mm;max-width:100%;height:auto;max-height:15mm;object-fit:contain;margin:0 auto 1mm">
      <div style="font-size:11px;font-weight:800;direction:rtl;white-space:nowrap;margin-bottom:1mm">طعم البحر على أصوله</div>
      <div style="font-size:10px;direction:ltr;unicode-bidi:isolate;white-space:nowrap">01 651 803&nbsp;&nbsp; | &nbsp;&nbsp;70 141 148</div>
      <div style="font-size:9px;margin-top:1.5mm;direction:rtl">برج أبي حيدر - الشارع الرئيسي - بجانب حلويات المصري</div>
    </div>

    <div style="border-top:1.5px solid #000;margin:3mm 0 2mm"></div>
    <div style="text-align:center;font-size:17px;font-weight:900;line-height:1.1">فاتورة طلب</div>
    <div style="text-align:center;font-size:10px;font-weight:700;margin-top:1mm">#${esc(orderShort||'طلب')}</div>

    <div style="display:flex;justify-content:space-between;gap:5mm;margin-top:2mm;font-size:9px;font-weight:700">
      <span>التاريخ: ${esc(date)}</span><span>الوقت: ${esc(time)}</span>
    </div>

    <div style="margin-top:2mm;padding:2mm 0;border-top:1px dashed #000;border-bottom:1px dashed #000;font-size:9.5px;line-height:1.45">
      <div><b>نوع الطلب:</b> ${esc(displayOrderType)}</div>
      <div><b>الزبون:</b> ${esc(o.customer_name||'غير محدد')}</div>
      <div><b>الهاتف:</b> <span dir="ltr" style="direction:ltr;unicode-bidi:isolate">${esc(o.customer_phone||'غير محدد')}</span></div>
      ${isDelivery?'<div><b>العنوان:</b> '+esc(o.customer_address||'غير محدد')+'</div>'+((meta.delivery_time)?'<div><b>وقت التوصيل:</b> <span dir="ltr">'+esc(meta.delivery_time)+'</span></div>':''):''}
    </div>

    <div class="receipt-items">
      <div class="receipt-item-head"><div>المجموع</div><div>السعر</div><div>الكمية</div><div>الصنف</div></div>
      ${rows||'<div style="padding:6px;text-align:center">لا توجد أصناف</div>'}
    </div>

    <div style="border-top:1px dashed #000;margin-top:2mm;padding-top:2mm;font-size:9.5px">
      <div style="display:grid;grid-template-columns:1fr 25mm;align-items:center;gap:2mm;margin-bottom:1.5mm"><b>المجموع قبل التوصيل</b><b style="text-align:left">${moneyHtml(subtotal)}</b></div>
      <div style="display:grid;grid-template-columns:1fr 25mm;align-items:center;gap:2mm;margin-bottom:1.5mm"><b>رسوم التوصيل</b><b style="text-align:left">${deliveryHtml}</b></div>
      <div style="display:grid;grid-template-columns:1fr 25mm;align-items:center;gap:2mm;padding:2mm 1mm;border-top:1.5px solid #000;border-bottom:1.5px solid #000;font-size:12px"><b>${finalLabel}</b><b style="text-align:left">${moneyHtml(finalValue)}</b></div>
      <div style="margin-top:2mm"><b>طريقة الدفع:</b> ${esc(meta.payment_label||'كاش')}</div>
    </div>

    ${cleanNotes?'<div style="margin-top:2mm;padding-top:2mm;border-top:1px dashed #000;font-size:9px"><b>ملاحظات:</b><div style="margin-top:1mm;line-height:1.45">'+esc(cleanNotes)+'</div></div>':''}

    <div style="border-top:1px dashed #000;margin-top:3mm;padding-top:3mm;text-align:center;font-size:12px;font-weight:900">شكراً لطلبكم ❤️</div>
    <div style="text-align:center;font-size:11px;font-weight:800;margin-top:1mm">TABBARA FISH</div>
  </div>`;

  let p=document.getElementById('posPrintArea');
  if(!p){p=document.createElement('div');p.id='posPrintArea';document.body.appendChild(p)}
  p.innerHTML=html;
  document.body.classList.add('printing-invoice');
  setTimeout(()=>{window.print();setTimeout(()=>document.body.classList.remove('printing-invoice'),300)},150);
}

function printDailyReport(){const rows=window.__reportRows||[],stats=window.__reportStats||buildReport(rows),date=window.__reportDate||new Date().toISOString().slice(0,10);const html=`<div style="width:80mm;font-family:Arial;direction:rtl;text-align:right;padding:8px;box-sizing:border-box"><h2 style="text-align:center;margin:0 0 5px">🐟 Tabbara Fish</h2><div style="text-align:center;font-weight:bold">تقرير المبيعات اليومية</div><div style="text-align:center;font-size:12px">${esc(date)}</div><div style="border-bottom:1px dashed #000;margin:8px 0"></div><div><b>عدد الطلبات:</b> ${stats.orders}<br><b>إجمالي المبيعات:</b> $${money(stats.total)}<br><b>دليفري:</b> $${money(stats.delivery)}<br><b>استلام:</b> $${money(stats.pickup)}<br><b>كاش:</b> $${money(stats.cash)}<br><b>بطاقة:</b> $${money(stats.card)}<br><b>تحويل:</b> $${money(stats.transfer)}<br><b>المفروض بالصندوق:</b> $${money(stats.cash)}</div><div style="border-bottom:1px dashed #000;margin:8px 0"></div><h3 style="margin:5px 0">📦 الأصناف المباعة</h3>${stats.products.length?stats.products.map(p=>`<div style="margin:5px 0;border-bottom:1px dotted #aaa;padding-bottom:4px"><b>${esc(p.name)}</b><br>الكمية: ${p.qtyLabel} — $${money(p.total)}</div>`).join(''):'<div>لا توجد مبيعات.</div>'}<div style="border-top:1px dashed #000;margin-top:8px;padding-top:7px;font-size:16px"><b>الإجمالي: $${money(stats.total)}</b></div><div style="text-align:center;margin-top:10px;font-size:11px">نهاية التقرير</div></div>`;let p=document.getElementById('posPrintArea');if(!p){p=document.createElement('div');p.id='posPrintArea';document.body.appendChild(p)}p.innerHTML=html;document.body.classList.add('printing-invoice');setTimeout(()=>{window.print();setTimeout(()=>document.body.classList.remove('printing-invoice'),300)},100)}
function buildReport(rows){const productsMap={};let total=0,cash=0,card=0,transfer=0,delivery=0,pickup=0;for(const o of rows){total+=Number(o.total||0);if(String(o.order_type||'').toLowerCase()==='delivery')delivery+=Number(o.total||0);else pickup+=Number(o.total||0);const meta=(Array.isArray(o.items)?o.items:[]).find(x=>x.__meta)||{};if(meta.payment_method==='card')card+=Number(o.total||0);else if(meta.payment_method==='transfer')transfer+=Number(o.total||0);else cash+=Number(o.total||0);for(const x of (Array.isArray(o.items)?o.items:[]).filter(x=>!x.__meta)){const k=x.name||x.label||'غير معروف';const qty=Number(x.weight ?? x.quantity ?? 1);const unit=Number(x.unitPrice ?? x.price ?? x.unit_price ?? 0);const storedTotal=Number(x.total ?? x.line_total);const lineTotal=Number.isFinite(storedTotal)&&storedTotal>0?storedTotal:qty*unit;if(!productsMap[k])productsMap[k]={name:k,qty:0,weight:0,total:0};productsMap[k].qty+=Number(x.quantity||0);productsMap[k].weight+=Number(x.weight||0);productsMap[k].total+=Number.isFinite(lineTotal)?lineTotal:0}}return{orders:rows.length,total,cash,card,transfer,delivery,pickup,products:Object.values(productsMap).sort((a,b)=>b.total-a.total).map(p=>({...p,qtyLabel:p.weight?money(p.weight)+' كغ':String(p.qty)}))}}
async function showOrders(){
  openModal('📋 الطلبات السابقة','<div id="ordersList" class="data-list"><div class="muted">⏳ جاري تحميل الطلبات...</div></div>');
  const host=document.getElementById('ordersList');
  try{
    const r=await api('/rest/v1/orders?select=*&order=created_at.desc&limit=200');
    if(!r.ok)throw new Error(await r.text());
    const rows=await r.json();
    window.__previousOrders=rows;
    if(!rows.length){host.innerHTML='<div class="empty-state">لا توجد طلبات سابقة.</div>';return}
    host.innerHTML=rows.map((o,i)=>{
      const items=(Array.isArray(o.items)?o.items:[]).filter(x=>!x.__meta);
      const date=o.created_at?new Date(o.created_at).toLocaleString('ar-LB',{dateStyle:'short',timeStyle:'short'}):'';
      const oid=esc(String(o.id||'')).replace(/'/g,"\\'");
      const short=String(o.id||'').replace(/-/g,'').slice(-6).toUpperCase()||String(i+1);
      const itemText=items.map(x=>`${esc(x.label||x.name||'صنف')} × ${esc(String(x.weight!=null?x.weight+' كغ':x.quantity||1))}`).join('، ')||'لا توجد أصناف';
      return `<div class="data-card">
        <div class="data-card-head"><b>#${esc(short)}</b><span>${esc(date)}</span></div>
        <div><b>${esc(o.customer_name||'غير محدد')}</b> — <span dir="ltr">${esc(o.customer_phone||'')}</span></div>
        <div class="muted">${esc(o.order_type||'')} · ${itemText}</div>
        <div class="data-card-total">$${money(o.total)}</div>
        <div class="data-card-actions">
          <button type="button" class="primary" onclick="viewOrderDetails('${oid}')">👁️ التفاصيل</button>
          <button type="button" class="primary" onclick="reprintOrder('${oid}')">🖨️ إعادة طباعة</button>
          <button type="button" class="danger" onclick="deletePreviousOrder('${oid}')">🗑️ إلغاء/حذف</button>
        </div>
      </div>`;
    }).join('');
  }catch(e){console.warn('showOrders',e);host.innerHTML='<div class="error-state">⚠️ تعذّر تحميل الطلبات. تأكد من الاتصال بقاعدة البيانات.</div>'}
}

function getPreviousOrder(id){return (window.__previousOrders||[]).find(o=>String(o.id)===String(id))||null}
function orderItemsSummary(o){const items=(Array.isArray(o?.items)?o.items:[]).filter(x=>!x.__meta);return items.map(x=>{const qty=Number(x.weight??x.quantity??1);const unit=Number(x.unitPrice??x.price??x.unit_price??0);const stored=Number(x.total??x.line_total);const line=Number.isFinite(stored)&&stored>0?stored:qty*unit;const label=x.label||x.name||'صنف';return `<div class="detail-item"><span>${esc(label)} × ${esc(String(x.weight!=null?x.weight+' كغ':x.quantity||1))}</span><b dir="ltr">$${money(line)}</b></div>`}).join('')||'<div class="muted">لا توجد أصناف.</div>'}
function viewOrderDetails(id){const o=getPreviousOrder(id);if(!o)return alert('الطلب غير موجود.');const meta=(Array.isArray(o.items)?o.items:[]).find(x=>x.__meta)||{};const date=o.created_at?new Date(o.created_at).toLocaleString('ar-LB',{dateStyle:'medium',timeStyle:'short'}):'';const short=String(o.id||'').replace(/-/g,'').slice(-6).toUpperCase();openModal('📋 تفاصيل الطلب #'+esc(short),`<div class="order-details"><div><b>التاريخ:</b> ${esc(date)}</div><div><b>نوع الطلب:</b> ${esc(o.order_type||'')}</div><div><b>الزبون:</b> ${esc(o.customer_name||'غير محدد')}</div><div><b>الهاتف:</b> <span dir="ltr">${esc(o.customer_phone||'')}</span></div>${String(o.order_type||'').toLowerCase()==='delivery'?`<div><b>العنوان:</b> ${esc(o.customer_address||'غير محدد')}</div>${meta.delivery_time?`<div><b>وقت التوصيل:</b> <span dir="ltr">${esc(meta.delivery_time)}</span></div>`:''}`:''}<div><b>طريقة الدفع:</b> ${esc(meta.payment_label||'كاش')}</div><hr><h4>الأصناف</h4>${orderItemsSummary(o)}<hr><div class="detail-total"><span>المجموع</span><b dir="ltr">$${money(o.total)}</b></div>${o.notes?`<div><b>ملاحظات:</b> ${esc(o.notes)}</div>`:''}<div class="data-card-actions"><button type="button" class="primary" onclick="reprintOrder('${esc(String(o.id||''))}')">🖨️ إعادة طباعة</button><button type="button" class="danger" onclick="deletePreviousOrder('${esc(String(o.id||''))}')">🗑️ إلغاء/حذف</button></div></div>`)}
function reprintOrder(id){const o=getPreviousOrder(id);if(!o)return alert('الطلب غير موجود.');closeModal();printOrder(o)}
async function deletePreviousOrder(id){const o=getPreviousOrder(id);if(!o)return alert('الطلب غير موجود.');const short=String(o.id||'').replace(/-/g,'').slice(-6).toUpperCase();if(!confirm(`هل تريد إلغاء وحذف الطلب #${short} نهائياً؟`))return;try{const r=await api(`/rest/v1/orders?id=eq.${encodeURIComponent(id)}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});if(!r.ok)throw new Error(await r.text());window.__previousOrders=(window.__previousOrders||[]).filter(x=>String(x.id)!==String(id));alert('✅ تم إلغاء وحذف الطلب.');showOrders()}catch(e){console.warn('deletePreviousOrder',e);alert('⚠️ لم يتم حذف الطلب. تأكد من صلاحية الحذف في Supabase.')}}

async function showCustomers(){
  openModal('👥 الزبائن','<div id="customersContent"><div class="search-row customer-search"><input id="customerSearch" type="search" placeholder="🔎 ابحث بالاسم أو رقم الهاتف" oninput="filterCustomers()"></div><div id="customersList" class="data-list"><div class="muted">⏳ جاري تحميل الزبائن...</div></div></div>');
  const host=document.getElementById('customersList');
  try{
    const r=await api('/rest/v1/customers?select=*&order=updated_at.desc&limit=500');
    if(!r.ok)throw new Error(await r.text());
    const rows=await r.json();window.__customers=rows;
    renderCustomers(rows);
  }catch(e){console.warn('showCustomers',e);host.innerHTML='<div class="error-state">⚠️ تعذّر تحميل الزبائن. تأكد من الاتصال بقاعدة البيانات.</div>'}
}
function renderCustomers(rows){const host=document.getElementById('customersList');if(!host)return;if(!rows.length){host.innerHTML='<div class="empty-state">لا يوجد زبائن مطابقون للبحث.</div>';return}host.innerHTML=rows.map(c=>{const id=String(c.id??c.phone??'');return `<div class="data-card"><div class="data-card-head"><b>${esc(c.name||'بدون اسم')}</b><span dir="ltr">${esc(c.phone||'')}</span></div><div>${esc(c.address||'العنوان غير مسجل')}</div>${c.notes?`<div class="muted">${esc(c.notes)}</div>`:''}<div class="data-card-actions"><button type="button" class="primary" onclick="editCustomer('${esc(id)}')">✏️ تعديل الزبون</button><button type="button" class="danger" onclick="deleteCustomer('${esc(id)}')">🗑️ حذف الزبون</button></div></div>`}).join('')}
function filterCustomers(){const q=String(document.getElementById('customerSearch')?.value||'').trim().toLowerCase();const rows=window.__customers||[];renderCustomers(rows.filter(c=>String(c.name||'').toLowerCase().includes(q)||String(c.phone||'').replace(/\D/g,'').includes(q.replace(/\D/g,''))))}
function editCustomer(id){const c=(window.__customers||[]).find(x=>String(x.id??x.phone??'')===String(id));if(!c)return alert('الزبون غير موجود.');const key=String(c.id??c.phone??'');openModal('✏️ تعديل الزبون',`<div class="form-grid customer-edit-form"><div class="full"><label>الاسم</label><input id="editCustomerName" class="modal-input" value="${esc(c.name||'')}"></div><div><label>رقم الهاتف</label><input id="editCustomerPhone" class="modal-input" type="tel" value="${esc(c.phone||'')}"></div><div class="full"><label>العنوان</label><input id="editCustomerAddress" class="modal-input" value="${esc(c.address||'')}"></div><div class="full"><label>ملاحظات</label><textarea id="editCustomerNotes" class="modal-input">${esc(c.notes||'')}</textarea></div><div class="full"><button type="button" class="primary" onclick="saveEditedCustomer('${esc(key)}')">💾 حفظ التعديل</button></div></div>`)}
async function saveEditedCustomer(oldKey){const name=document.getElementById('editCustomerName').value.trim(),phone=normalizePhone(document.getElementById('editCustomerPhone').value),address=document.getElementById('editCustomerAddress').value.trim(),notes=document.getElementById('editCustomerNotes').value.trim();if(!phone)return alert('أدخل رقم الهاتف.');const original=(window.__customers||[]).find(c=>String(c.id??c.phone??'')===String(oldKey));if(!original)return alert('الزبون غير موجود.');try{let path;if(original.id!=null){path=`/rest/v1/customers?id=eq.${encodeURIComponent(original.id)}`}else{path=`/rest/v1/customers?phone=eq.${encodeURIComponent(original.phone)}`}const r=await api(path,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({name,phone,address,notes,updated_at:new Date().toISOString()})});if(!r.ok)throw new Error(await r.text());const updated={...original,name,phone,address,notes};window.__customers=(window.__customers||[]).map(c=>String(c.id??c.phone??'')===String(oldKey)?updated:c);const cached=JSON.parse(localStorage.getItem(CUSTOMER_STORAGE_KEY)||'[]');const next=Array.isArray(cached)?cached:[];const idx=next.findIndex(c=>normalizePhone(c.phone)===normalizePhone(original.phone));if(idx>=0)next[idx]=updated;else next.unshift(updated);localStorage.setItem(CUSTOMER_STORAGE_KEY,JSON.stringify(next.slice(0,500)));alert('✅ تم تعديل بيانات الزبون.');showCustomers()}catch(e){console.warn('saveEditedCustomer',e);alert('⚠️ لم يتم حفظ التعديل.')}}
async function deleteCustomer(id){const c=(window.__customers||[]).find(x=>String(x.id??x.phone??'')===String(id));if(!c)return alert('الزبون غير موجود.');const label=c.name||c.phone||'هذا الزبون';if(!confirm(`هل أنت متأكد من حذف ${label} نهائياً؟`))return;try{const path=c.id!=null?`/rest/v1/customers?id=eq.${encodeURIComponent(c.id)}`:`/rest/v1/customers?phone=eq.${encodeURIComponent(c.phone)}`;const r=await api(path,{method:'DELETE',headers:{Prefer:'return=minimal'}});if(!r.ok)throw new Error(await r.text());window.__customers=(window.__customers||[]).filter(x=>String(x.id??x.phone??'')!==String(id));const cached=JSON.parse(localStorage.getItem(CUSTOMER_STORAGE_KEY)||'[]');localStorage.setItem(CUSTOMER_STORAGE_KEY,JSON.stringify((Array.isArray(cached)?cached:[]).filter(x=>normalizePhone(x.phone)!==normalizePhone(c.phone))));alert('✅ تم حذف الزبون.');renderCustomers(window.__customers)}catch(e){console.warn('deleteCustomer',e);alert('⚠️ لم يتم حذف الزبون. تأكد من صلاحية الحذف في Supabase.')}}

async function showReports(){
  openModal('📊 تقارير المبيعات','<div id="reportsContent"><div class="muted">⏳ جاري تحميل تقرير المبيعات...</div></div>');
  const host=document.getElementById('reportsContent');
  try{
    const r=await api('/rest/v1/orders?select=*&order=created_at.desc&limit=2000');
    if(!r.ok)throw new Error(await r.text());
    const rows=await r.json();
    const stats=buildReport(rows);
    window.__reportRows=rows;window.__reportStats=stats;window.__reportDate=new Date().toLocaleDateString('ar-LB');
    const top=stats.products.slice(0,20);
    host.innerHTML=`<div class="report-summary-grid"><div class="report-stat"><b>الطلبات</b><strong>${stats.orders}</strong></div><div class="report-stat"><b>المبيعات</b><strong>$${money(stats.total)}</strong></div><div class="report-stat"><b>كاش</b><strong>$${money(stats.cash)}</strong></div><div class="report-stat"><b>بطاقة</b><strong>$${money(stats.card)}</strong></div></div><div class="report-breakdown"><b>دليفري:</b> $${money(stats.delivery)} &nbsp; | &nbsp; <b>استلام:</b> $${money(stats.pickup)} &nbsp; | &nbsp; <b>تحويل:</b> $${money(stats.transfer)}</div><h4 style="margin:16px 0 8px">📦 الأصناف المباعة</h4>${top.length?top.map(p=>`<div class="report-row"><span>${esc(p.name)} × ${esc(p.qtyLabel)}</span><b>$${money(p.total)}</b></div>`).join(''):'<div class="empty-state">لا توجد مبيعات.</div>'}<button type="button" class="primary" style="width:100%;margin-top:14px" onclick="printDailyReport()">🖨️ طباعة التقرير</button>`;
  }catch(e){console.warn('showReports',e);host.innerHTML='<div class="error-state">⚠️ تعذّر تحميل تقرير المبيعات. تأكد من الاتصال بقاعدة البيانات.</div>'}
}

function loadSettings(){deliveryCharge=Number(localStorage.getItem(DELIVERY_CHARGE_KEY));if(!Number.isFinite(deliveryCharge))deliveryCharge=DEFAULT_DELIVERY_CHARGE;grillSurcharge=Number(localStorage.getItem(GLOBAL_GRILL_KEY));if(!Number.isFinite(grillSurcharge))grillSurcharge=DEFAULT_GRILL_SURCHARGE;frySurcharge=Number(localStorage.getItem(GLOBAL_FRY_KEY));if(!Number.isFinite(frySurcharge))frySurcharge=DEFAULT_FRY_SURCHARGE}
function loadMenu(){try{const x=JSON.parse(localStorage.getItem(MENU_STORAGE_KEY)||'null');if(Array.isArray(x)&&x.length){menu=x;return}}catch{}menu=JSON.parse(JSON.stringify(DEFAULT_MENU));localStorage.setItem(MENU_STORAGE_KEY,JSON.stringify(menu))}
function cloudRowToLocal(r){const d=r.data&&typeof r.data==='object'?r.data:{};const cat={'الأسماك':'🐟 الأسماك','ثمار البحر':'🦐 ثمار البحر','الوجبات والساندويش':'🍽️ الوجبات','الوجبات':'🍽️ الوجبات','الساندويشات':'🍽️ الوجبات','العروض':'🎁 العروض','المقبلات':'🥗 المقبلات','السلطات':'🥬 السلطات','المشروبات':'🥤 المشروبات'};const def=DEFAULT_MENU.find(x=>String(x.id)===String(r.id));const item={id:String(r.id),name:r.name||'',category:cat[r.category]||r.category||'',type:r.type||def?.type||'fixed',available:r.available!==false};if(item.type==='weight'){item.pricing={base:Number(d.base??d.basePrice??def?.pricing?.base??0)}}else if(item.type==='sizes'){item.sizes={...(d.sizes||def?.sizes||{})}}else if(item.type==='meal')item.prices={وجبة:Number(d.meal??d.وجبة??d.prices?.وجبة??0),ساندويش:Number(d.sandwich??d.ساندويش??d.prices?.ساندويش??0)};else if(item.type==='offer'){item.price=Number(d.price??r.price??0);item.details=d.details||'';item.items=Array.isArray(d.items)?d.items:[]}else item.price=Number(d.price??r.price??def?.price??0);return item}
function localToCloudRow(i){let data={};if(i.type==='weight'){data.base=Number(i.pricing?.base||0)}else if(i.type==='sizes'){data.sizes={...(i.sizes||{})}}else if(i.type==='meal'){data.meal=Number(i.prices?.وجبة||0);data.sandwich=Number(i.prices?.ساندويش||0)}else if(i.type==='offer'){data.price=Number(i.price||0);data.details=i.details||'';data.items=Array.isArray(i.items)?i.items:[]}else data.price=Number(i.price||0);return{id:String(i.id),name:i.name||'',category:i.category||'',type:i.type||'fixed',available:i.available!==false,data,updated_at:new Date().toISOString()}}
async function syncMenuFromCloud(){if(!navigator.onLine)return;try{const r=await api('/rest/v1/pos_menu?select=*&limit=1000');if(r.ok){const rows=await r.json();if(rows.length){menu=rows.map(cloudRowToLocal);saveMenuLocal();renderCategories();renderItems()}}}catch(e){console.warn(e)}}
async function syncMenuToCloud(){if(!navigator.onLine)return;try{for(const i of menu)await api('/rest/v1/pos_menu',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(localToCloudRow(i))})}catch(e){console.warn(e)}}
async function syncOneMenuItem(i){if(!navigator.onLine||!i)return;try{await api('/rest/v1/pos_menu',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(localToCloudRow(i))})}catch(e){console.warn(e)}}
function openModal(title,body){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal-box"><div class="modal-header"><h3>${title}</h3><button type="button" onclick="closeModal()">✕</button></div><div class="modal-body">${body}</div></div></div>`;document.body.style.overflow='hidden'}
function closeModal(){const root=document.getElementById('modalRoot');if(root)root.innerHTML='';document.body.style.overflow='';}
function refreshManagerKeepScroll(){
 const b=document.querySelector('#modalRoot .modal-body');
 const y=b?b.scrollTop:0;
 renderMenuManagerContent();
 requestAnimationFrame(()=>{const nb=document.querySelector('#modalRoot .modal-body');if(nb)nb.scrollTop=y});
}
function setManagerCategory(category){managerCategory=category;renderMenuManagerContent();}
function renderMenuManagerContent(){
 const host=document.getElementById('managerContent'); if(!host)return;
 const list=menu.filter(i=>managerCategory===MEALS_CATEGORY||managerCategory===SANDWICHES_CATEGORY?i.type==='meal':i.category===managerCategory);
 host.innerHTML=`<div class="manager-section-title"><h3>${esc(managerCategory)}</h3><span class="muted">${list.length} صنف</span></div><div class="manager-grid">${list.map(managerCard).join('')||'<p class="muted">لا توجد أصناف بهذا التصنيف.</p>'}</div>`;
}
function showMenuManager(){
 managerCategory=CATEGORIES.includes(managerCategory)?managerCategory:CATEGORIES[0];
 const body=`<div class="manager-settings"><h3>⚙️ إعدادات عامة</h3><div class="form-grid"><div><label>كلفة التوصيل ($)</label><input id="managerDelivery" type="number" step="0.01" min="0" value="${money(deliveryCharge)}"></div><div><label>إضافة القلي والشوي لكل كغ ($)</label><input id="managerCooking" type="number" step="0.01" min="0" value="${money((Number(frySurcharge)+Number(grillSurcharge))/2)}"></div><div class="full"><button class="primary" onclick="saveManagerSettings()">💾 حفظ الإعدادات</button></div></div></div><hr><div class="manager-toolbar"><h3>🍽️ إدارة المنيو</h3><div><button class="primary" onclick="openAddItemEditor()">➕ إضافة صنف</button> <button class="primary" onclick="openAddOfferEditor()">🎁 إضافة عرض</button></div></div><p class="muted">اختار التصنيف أولاً، وبعدها بتشوف أصنافه وحدها. فيك تعدّل، تغيّر السعر، تخفي/تظهر، أو تلغي الصنف.</p><div class="manager-category-tabs">${CATEGORIES.map(c=>`<button class="manager-tab ${c===managerCategory?'active':''}" onclick="setManagerCategory('${esc(c).replace(/'/g,"\\'")}')">${esc(c)}</button>`).join('')}</div><div id="managerContent"></div>`;
 openModal('⚙️ إدارة المنيو',body);renderMenuManagerContent();
}
function managerCard(i){const id=esc(i.id).replace(/'/g,"\\'");const sold=i.available===false;let editor='';if(i.type==='offer')editor=`<div class="offer-manager-details"><b>💰 السعر: $${money(i.price)}</b><p>${esc(i.details||'لا توجد تفاصيل')}</p><div class="muted">${(i.items||[]).map(x=>esc(x.name)+(x.quantity>1?' × '+x.quantity:'')).join('، ')||'لا توجد أصناف ضمن العرض'}</div></div>`;else if(i.type==='weight')editor=`<div class="price-editor"><label>السعر الأساسي / كغ ($)</label><input id="price-${esc(i.id)}" type="number" step="0.01" min="0" value="${money(i.pricing?.base)}"><button class="primary" onclick="saveItemPrice('${id}')">💾 حفظ السعر</button></div>`;else if(i.type==='sizes')editor=`<div class="price-editor sizes-editor">${Object.entries(i.sizes||{}).map(([size,p])=>`<div><label>${esc(size)} ($)</label><input id="price-${esc(i.id)}-${esc(size)}" type="number" step="0.01" min="0" value="${money(p)}"></div>`).join('')}<button class="primary" onclick="saveItemPrice('${id}')">💾 حفظ الأسعار</button></div>`;else if(i.type==='meal')editor=`<div class="price-editor"><div><label>وجبة ($)</label><input id="price-${esc(i.id)}-meal" type="number" step="0.01" min="0" value="${money(i.prices?.وجبة)}"></div><div><label>ساندويش ($)</label><input id="price-${esc(i.id)}-sandwich" type="number" step="0.01" min="0" value="${money(i.prices?.ساندويش)}"></div><button class="primary" onclick="saveItemPrice('${id}')">💾 حفظ الأسعار</button></div>`;else editor=`<div class="price-editor"><label>السعر ($)</label><input id="price-${esc(i.id)}" type="number" step="0.01" min="0" value="${money(i.price)}"><button class="primary" onclick="saveItemPrice('${id}')">💾 حفظ السعر</button></div>`;return `<div class="manager-card ${sold?'manager-sold':''}"><h4>${i.type==='offer'?'🎁 ':''}${esc(i.name)}</h4><div class="muted">${esc(i.category)}</div>${editor}<div class="manager-actions"><button class="${sold?'primary':'danger'}" onclick="toggleAvailability('${id}')">${sold?'✅ إعادة متوفر':'⛔ إخفاء/منتهي'}</button>${i.type==='offer'?`<button class="primary" onclick="openEditOffer('${id}')">✏️ تعديل العرض</button>`:`<button class="primary" onclick="openEditItem('${id}')">✏️ تعديل الصنف</button>`}<button class="danger" onclick="deleteMenuItem('${id}')">🗑️ إلغاء الصنف</button></div></div>`}
function categoryOptions(selected){const effective=(selected===COMBINED_MEALS_CATEGORY?MEALS_CATEGORY:selected);return CATEGORIES.map(c=>`<option value="${esc(c)}" ${c===effective?'selected':''}>${esc(c)}</option>`).join('')}
function openAddItemEditor(){openItemEditor(null)}
function openEditItem(id){const i=menu.find(x=>x.id===id);if(i)openItemEditor(i)}
function openItemEditor(item){const i=item||{id:'',name:'',category:CATEGORIES[0],type:'fixed',price:0,available:true};openModal(item?'✏️ تعديل صنف':'➕ إضافة صنف',`<div class="form-grid"><div><label>اسم الصنف</label><input id="editName" class="modal-input" value="${esc(i.name)}"></div><div><label>التصنيف</label><select id="editCategory" class="modal-input">${categoryOptions(i.category)}</select></div><div><label>نوع الصنف</label><select id="editType" class="modal-input" onchange="refreshItemEditor()"><option value="fixed" ${i.type==='fixed'?'selected':''}>سعر عادي</option><option value="weight" ${i.type==='weight'?'selected':''}>بالكيلو</option><option value="sizes" ${i.type==='sizes'?'selected':''}>أحجام</option><option value="meal" ${i.type==='meal'?'selected':''}>صنف بوجبة/ساندويش</option></select></div><div id="itemEditorFields"></div><div class="full"><button class="primary" onclick="saveItemEditor('${esc(i.id).replace(/'/g,"\\'")}')">💾 حفظ</button></div></div>`);window.__editingItem=i;refreshItemEditor()}
function refreshItemEditor(){const i=window.__editingItem||{};const type=document.getElementById('editType').value;let html='';if(type==='weight')html=`<label>السعر الأساسي / كغ</label><input id="editBase" class="modal-input" type="number" step="0.01" value="${money(i.pricing?.base)}">`;else if(type==='sizes'){const sizes=i.sizes||{صغير:0,وسط:0,كبير:0};html=`<label>الأحجام والأسعار (مثال: صغير:5,وسط:8,كبير:11)</label><input id="editSizes" class="modal-input" value="${esc(Object.entries(sizes).map(([k,v])=>k+':'+v).join(','))}">`;}else if(type==='meal')html=`<label>وجبة ($)</label><input id="editMeal" class="modal-input" type="number" step="0.01" value="${money(i.prices?.وجبة)}"><label>ساندويش ($)</label><input id="editSandwich" class="modal-input" type="number" step="0.01" value="${money(i.prices?.ساندويش)}>`;else html=`<label>السعر ($)</label><input id="editPrice" class="modal-input" type="number" step="0.01" value="${money(i.price)}">`;document.getElementById('itemEditorFields').innerHTML=html}
async function saveItemEditor(oldId){const name=document.getElementById('editName').value.trim();if(!name)return alert('اكتب اسم الصنف.');const type=document.getElementById('editType').value;let i=oldId?menu.find(x=>x.id===oldId):null;if(!i){i={id:'item_'+Date.now(),name,category:'',type,available:true};menu.push(i)}i.name=name;const chosenCategory=document.getElementById('editCategory').value;i.category=chosenCategory;i.type=type;if(type==='weight'){i.pricing={base:Number(document.getElementById('editBase').value)||0};delete i.stock;delete i.price;delete i.sizes;delete i.prices}else if(type==='sizes'){const obj={};for(const part of document.getElementById('editSizes').value.split(',')){const [k,v]=part.split(':');if(k&&Number.isFinite(Number(v)))obj[k.trim()]=Number(v)}if(!Object.keys(obj).length)return alert('أدخل الأحجام والأسعار.');i.sizes=obj;delete i.price;delete i.pricing;delete i.prices}else if(type==='meal'){i.prices={وجبة:Number(document.getElementById('editMeal').value)||0,ساندويش:Number(document.getElementById('editSandwich').value)||0};delete i.price;delete i.sizes;delete i.pricing}else{i.price=Number(document.getElementById('editPrice').value)||0;delete i.sizes;delete i.pricing;delete i.prices}saveMenuLocal();syncOneMenuItem(i);renderCategories();renderItems();refreshManagerKeepScroll()}
function openAddOfferEditor(){openOfferEditor(null)}
function openEditOffer(id){const i=menu.find(x=>x.id===id);if(i)openOfferEditor(i)}
function offerItemOptions(selected){return menu.filter(x=>x.type!=='offer').map(x=>`<label class="offer-item-row"><input type="checkbox" value="${esc(x.id)}" ${(selected||[]).some(s=>s.id===x.id)?'checked':''}> ${esc(x.name)} <input class="offer-item-qty" data-id="${esc(x.id)}" type="number" min="1" step="1" value="${Number((selected||[]).find(s=>s.id===x.id)?.quantity||1)}"></label>`).join('')}
function openOfferEditor(item){const i=item||{id:'',name:'',category:'🎁 العروض',type:'offer',price:0,details:'',items:[],available:true};window.__editingOffer=i;openModal(item?'✏️ تعديل العرض':'🎁 إضافة عرض',`<div class="form-grid"><div><label>اسم العرض</label><input id="offerName" class="modal-input" value="${esc(i.name)}"></div><div><label>سعر العرض ($)</label><input id="offerPrice" class="modal-input" type="number" step="0.01" value="${money(i.price)}"></div><div class="full"><label>تفاصيل العرض</label><textarea id="offerDetails" class="modal-input" rows="3">${esc(i.details||'')}</textarea></div><div class="full"><label>الأصناف الموجودة ضمن العرض</label><div class="offer-items-picker">${offerItemOptions(i.items)}</div></div><div class="full"><button class="primary" onclick="saveOfferEditor('${esc(i.id).replace(/'/g,"\\'")}')">💾 حفظ العرض</button></div></div>`)}
async function saveOfferEditor(oldId){const name=document.getElementById('offerName').value.trim(),price=Number(document.getElementById('offerPrice').value);if(!name||!Number.isFinite(price)||price<0)return alert('تأكد من اسم العرض والسعر.');let i=oldId?menu.find(x=>x.id===oldId):null;if(!i){i={id:'offer_'+Date.now(),type:'offer',available:true,category:'🎁 العروض'};menu.push(i)}i.name=name;i.price=price;i.details=document.getElementById('offerDetails').value.trim();i.items=[...document.querySelectorAll('.offer-items-picker input[type=checkbox]:checked')].map(cb=>{const src=menu.find(x=>x.id===cb.value);const q=Number(document.querySelector(`.offer-item-qty[data-id="${cb.value}"]`)?.value||1);return{id:src.id,name:src.name,quantity:q}});saveMenuLocal();syncOneMenuItem(i);renderCategories();renderItems();refreshManagerKeepScroll()}
async function deleteMenuItem(id){const i=menu.find(x=>x.id===id);if(!i)return;if(!confirm(`هل تريد إلغاء الصنف «${i.name}» نهائياً من إدارة المنيو؟`))return;menu=menu.filter(x=>x.id!==id);saveMenuLocal();if(navigator.onLine){api(`/rest/v1/pos_menu?id=eq.${encodeURIComponent(id)}`,{method:'DELETE'}).catch(e=>console.warn(e))}renderCategories();renderItems();refreshManagerKeepScroll()}
async function saveManagerSettings(){
 const d=Number(document.getElementById('managerDelivery').value),c=Number(document.getElementById('managerCooking').value);
 if(!Number.isFinite(d)||d<0||!Number.isFinite(c)||c<0)return alert('أدخل قيم صحيحة.');
 deliveryCharge=d;frySurcharge=c;grillSurcharge=c;
 localStorage.setItem(DELIVERY_CHARGE_KEY,String(d));localStorage.setItem(GLOBAL_FRY_KEY,String(c));localStorage.setItem(GLOBAL_GRILL_KEY,String(c));
 Promise.all([saveSetting('delivery_charge',d),saveSetting('fish_fry_surcharge',c),saveSetting('fish_grill_surcharge',c)]);
 renderCart();refreshManagerKeepScroll();alert('✅ تم حفظ كلفة التوصيل وإضافة القلي والشوي.');
}
async function saveItemPrice(id){
 const i=menu.find(x=>x.id===id);if(!i)return;
 if(i.type==='weight'){
  const n=Number(document.getElementById('price-'+id).value);if(!Number.isFinite(n)||n<0)return alert('السعر غير صحيح.');i.pricing=i.pricing||{};i.pricing.base=n;
 }else if(i.type==='sizes'){
  const next={};for(const size of Object.keys(i.sizes||{})){const el=document.getElementById('price-'+id+'-'+size);const n=Number(el?.value);if(!Number.isFinite(n)||n<0)return alert('السعر غير صحيح.');next[size]=n}i.sizes=next;
 }else if(i.type==='meal'){
  const a=Number(document.getElementById('price-'+id+'-meal').value),b=Number(document.getElementById('price-'+id+'-sandwich').value);if(!Number.isFinite(a)||a<0||!Number.isFinite(b)||b<0)return alert('السعر غير صحيح.');i.prices={وجبة:a,ساندويش:b};
 }else{
  const n=Number(document.getElementById('price-'+id).value);if(!Number.isFinite(n)||n<0)return alert('السعر غير صحيح.');i.price=n;
 }
 saveMenuLocal();syncOneMenuItem(i);renderItems();refreshManagerKeepScroll();
}
